import * as THREE from 'three/webgpu';
import { color, mix, uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.userData.handlers = {};
  const timelines = [];
  const disposables = [];

  // ===== BACKGROUND PLANE =====
  const bgGeometry = new THREE.PlaneGeometry(6.8, 2.0);
  const colorA = new THREE.Color('#121218');
  const colorB = new THREE.Color('#0b0b10');

  const uvNode = uv();
  const gradientColor = mix(
    color(colorA),
    color(colorB),
    uvNode.y
  );

  const bgMaterial = new THREE.MeshStandardNodeMaterial();
  bgMaterial.colorNode = gradientColor;
  bgMaterial.roughnessValue = 0.6;
  bgMaterial.metalnessValue = 0.2;
  bgMaterial.transparent = true;
  bgMaterial.opacity = 0;

  const bgPlane = new THREE.Mesh(bgGeometry, bgMaterial);
  group.add(bgPlane);
  disposables.push(bgGeometry, bgMaterial);

  // ===== HAIRLINE RULES =====
  const hairlineGeometry = new THREE.PlaneGeometry(6.8, 0.006);
  const hairlineMaterial = new THREE.MeshStandardNodeMaterial();
  hairlineMaterial.colorNode = color(new THREE.Color('#23232b'));
  hairlineMaterial.transparent = true;
  hairlineMaterial.opacity = 0;
  disposables.push(hairlineGeometry, hairlineMaterial);

  const topHairline = new THREE.Mesh(hairlineGeometry, hairlineMaterial);
  topHairline.position.z = 0.001;
  topHairline.position.y = 0.997;
  group.add(topHairline);

  const bottomHairline = new THREE.Mesh(hairlineGeometry, hairlineMaterial);
  bottomHairline.position.z = 0.001;
  bottomHairline.position.y = -0.5;
  group.add(bottomHairline);

  // ===== ACCENT BAR =====
  const accentGeometry = new THREE.PlaneGeometry(0.3, 0.02);
  const accentMaterial = new THREE.MeshStandardNodeMaterial();
  accentMaterial.colorNode = color(new THREE.Color('#ff2a38'));
  accentMaterial.emissiveIntensity = 1.4;
  accentMaterial.transparent = true;
  accentMaterial.opacity = 0;
  disposables.push(accentGeometry, accentMaterial);

  const accentBar = new THREE.Mesh(accentGeometry, accentMaterial);
  accentBar.position.set(-2.4, -0.35, 0.001);
  group.add(accentBar);

  // ===== TEXT ELEMENTS =====
  const textItems = [];
  const allMaterials = [bgMaterial, hairlineMaterial, accentMaterial];

  // Wordmark
  const wordmark = ctx.fontAtlas.createText('NOVA ATELIER', {
    fontSize: 34,
    fontWeight: 600,
    family: 'Lora',
    letterSpacing: 0.02,
  });
  if (wordmark.material) {
    wordmark.material.transparent = true;
    wordmark.material.opacity = 0;
    allMaterials.push(wordmark.material);
  }
  wordmark.position.set(-2.4, 0.3, 0.001);
  group.add(wordmark);
  textItems.push(wordmark);

  // Helper function to create column
  function createColumn(headerText, links, xPos) {
    const header = ctx.fontAtlas.createText(headerText, {
      fontSize: 9,
      fontWeight: 700,
      family: 'JetBrains Mono',
      letterSpacing: 0.12,
    });
    if (header.material) {
      header.material.transparent = true;
      header.material.opacity = 0;
      allMaterials.push(header.material);
    }
    header.position.set(xPos, 0.7, 0.001);
    group.add(header);
    textItems.push(header);

    links.forEach((linkText, index) => {
      const link = ctx.fontAtlas.createText(linkText, {
        fontSize: 13,
        fontWeight: 400,
        family: 'JetBrains Mono',
        letterSpacing: 0,
      });
      if (link.material) {
        link.material.transparent = true;
        link.material.opacity = 0;
        link.material.color = new THREE.Color('#e8ecf2');
        allMaterials.push(link.material);
      }
      const yPos = 0.4 - index * 0.234;
      link.position.set(xPos, yPos, 0.001);
      group.add(link);
      textItems.push(link);
      setupLinkHover(link);
    });
  }

  createColumn('ATELIER', ['Features', 'Collection', 'Pricing'], -0.5);
  createColumn('COMPANY', ['Journal', 'Visit the Atelier', 'Contact'], 1.0);
  createColumn('LEGAL', ['Privacy', 'Terms', 'Warranty'], 2.5);

  // Legal line
  const legalText = ctx.fontAtlas.createText('(c) 2026 Nova Atelier. All rights reserved. Machined in Geneva.', {
    fontSize: 9,
    fontWeight: 400,
    family: 'JetBrains Mono',
    letterSpacing: 0.04,
  });
  if (legalText.material) {
    legalText.material.transparent = true;
    legalText.material.opacity = 0;
    allMaterials.push(legalText.material);
  }
  legalText.position.set(0, -0.875, 0.001);
  group.add(legalText);
  textItems.push(legalText);

  // ===== MOUNT ANIMATION =====
  group.position.y = 0.2;

  const tl = gsap.timeline();

  tl.to(group.position, {
    y: 0,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
  }, 0);

  allMaterials.forEach(material => {
    tl.to(material, {
      opacity: 1,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    }, 0);
  });

  timelines.push(tl);

  // ===== LINK HOVER INTERACTION =====
  function setupLinkHover(linkObject) {
    const hoverColor = new THREE.Color('#ff2a38');

    if (!linkObject.material) return;

    const originalColor = linkObject.material.color.clone();

    linkObject.userData.onHover = () => {
      gsap.to(linkObject.material.color, {
        r: hoverColor.r,
        g: hoverColor.g,
        b: hoverColor.b,
        duration: 0.14,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      });
      gsap.to(linkObject.position, {
        z: 0.02,
        duration: 0.14,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      });
    };

    linkObject.userData.onUnhover = () => {
      gsap.to(linkObject.material.color, {
        r: originalColor.r,
        g: originalColor.g,
        b: originalColor.b,
        duration: 0.14,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      });
      gsap.to(linkObject.position, {
        z: 0.001,
        duration: 0.14,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      });
    };
  }

  // ===== CLEANUP =====
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    disposables.forEach(item => {
      if (item && item.dispose) {
        item.dispose();
      }
    });
  };

  return group;
}
